SET check_function_bodies = off;
CREATE OR REPLACE FUNCTION public.get_user_tenant_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT tenant_id FROM public.profiles WHERE user_id = _user_id LIMIT 1; $function$;
CREATE TABLE public.accounting_config (tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, posting_mode text DEFAULT 'shadow'::text NOT NULL, shadow_since timestamp with time zone DEFAULT now() NOT NULL, activated_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, employee_social_rate numeric DEFAULT 0.056 NOT NULL, employer_social_rate numeric DEFAULT 0.154 NOT NULL, income_tax_rate numeric DEFAULT 0 NOT NULL, daily_worker_withholding_rate numeric DEFAULT 0.05 NOT NULL, corporate_tax_rate numeric DEFAULT 0.30 NOT NULL, minimum_tax_rate numeric DEFAULT 0.005 NOT NULL, vat_rate numeric DEFAULT 18 NOT NULL, country_code text DEFAULT 'SN'::text NOT NULL, PRIMARY KEY (tenant_id), CHECK ((posting_mode = ANY (ARRAY['off'::text, 'shadow'::text, 'live'::text]))));
CREATE TABLE public.accounting_shadow_entries (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, event_type text NOT NULL, entry_date date NOT NULL, journal_code text NOT NULL, description text, source_table text, source_id uuid, lines jsonb NOT NULL, total_amount numeric(18,2) DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, status text DEFAULT 'pending'::text NOT NULL, tx_type text DEFAULT 'od'::text NOT NULL, reviewed_by uuid, reviewed_at timestamp with time zone, reject_reason text, posted_transaction_id uuid, PRIMARY KEY (id));
CREATE TABLE public.accounts (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, account_name text NOT NULL, account_type cash_account_type NOT NULL, bank_name text, account_number text, iban text, swift text, currency text DEFAULT 'XOF'::text NOT NULL, current_balance numeric(18,2) DEFAULT 0 NOT NULL, initial_balance numeric(18,2) DEFAULT 0 NOT NULL, chart_account_id uuid, is_active boolean DEFAULT true NOT NULL, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, balance numeric GENERATED ALWAYS AS (current_balance) STORED, deleted_at timestamp with time zone, PRIMARY KEY (id));
CREATE TABLE public.chart_of_accounts (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, account_number text NOT NULL, account_name text NOT NULL, account_type account_type NOT NULL, account_class integer NOT NULL, parent_account_id uuid, description text, is_active boolean DEFAULT true NOT NULL, is_system boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, deleted_at timestamp with time zone, PRIMARY KEY (id), UNIQUE (tenant_id, account_number));
CREATE TABLE public.clients (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, name text NOT NULL, client_type client_type DEFAULT 'local'::client_type NOT NULL, contact_person text, phone text, email text, address text, city text, country text DEFAULT 'Sénégal'::text, tax_id text, registration_number text, payment_terms text, credit_limit numeric DEFAULT 0 NOT NULL, current_balance numeric DEFAULT 0 NOT NULL, notes text, is_active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, deleted_at timestamp with time zone, PRIMARY KEY (id));
CREATE TABLE public.document_sequences (tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, doc_type text NOT NULL, year integer NOT NULL, last_number integer DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (tenant_id, doc_type, year));
CREATE TABLE public.domain_events (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb DEFAULT '{}'::jsonb NOT NULL, occurred_at timestamp with time zone DEFAULT now() NOT NULL, processed_at timestamp with time zone, processing_error text, created_by uuid, PRIMARY KEY (id));
CREATE TABLE public.fiscal_periods (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, fiscal_year_id uuid NOT NULL, period_number integer NOT NULL, period_start date NOT NULL, period_end date NOT NULL, status fiscal_period_status DEFAULT 'open'::fiscal_period_status NOT NULL, closed_at timestamp with time zone, closed_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, UNIQUE (fiscal_year_id, period_number), PRIMARY KEY (id));
CREATE TABLE public.fiscal_years (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, year integer NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status fiscal_period_status DEFAULT 'open'::fiscal_period_status NOT NULL, closed_at timestamp with time zone, closed_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id), UNIQUE (tenant_id, year));
CREATE TABLE public.inventory_items (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, warehouse_id uuid, name text DEFAULT ''::text NOT NULL, sku text, category text, unit_of_measure text DEFAULT 'unité'::text NOT NULL, quantity numeric DEFAULT 0 NOT NULL, reserved_quantity numeric DEFAULT 0 NOT NULL, unit_cost numeric DEFAULT 0 NOT NULL, cmp numeric DEFAULT 0 NOT NULL, reorder_level numeric DEFAULT 0 NOT NULL, notes text, is_active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, item_category text GENERATED ALWAYS AS (category) STORED, quantity_on_hand numeric GENERATED ALWAYS AS (quantity) STORED, item_name text GENERATED ALWAYS AS (name) STORED, storage_location text, item_code text, deleted_at timestamp with time zone, description text, total_stock_value numeric GENERATED ALWAYS AS ((COALESCE(quantity, (0)::numeric) * COALESCE(unit_cost, (0)::numeric))) STORED, last_purchase_date date, last_purchase_price numeric DEFAULT 0 NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.inventory_valuation_layers (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, inventory_item_id uuid NOT NULL, movement_type text NOT NULL, source_type text, reference_id uuid, quantity numeric NOT NULL, remaining_quantity numeric NOT NULL, unit_cost numeric(15,2) DEFAULT 0 NOT NULL, total_cost numeric(15,2) DEFAULT 0 NOT NULL, layer_date date DEFAULT CURRENT_DATE NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, notes text, total_value numeric(15,2) GENERATED ALWAYS AS (total_cost) STORED, PRIMARY KEY (id));
CREATE TABLE public.journal_entries (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, transaction_id uuid, entry_date date DEFAULT CURRENT_DATE NOT NULL, journal_code text DEFAULT 'OD'::text NOT NULL, account_id uuid NOT NULL, account_number text, description text, debit numeric(15,2) DEFAULT 0 NOT NULL, credit numeric(15,2) DEFAULT 0 NOT NULL, reference text, fiscal_period_id uuid, is_locked boolean DEFAULT false NOT NULL, created_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, account_name text, PRIMARY KEY (id));
CREATE TABLE public.payments (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, sale_id uuid, client_id uuid, amount numeric DEFAULT 0 NOT NULL, payment_method text DEFAULT 'cash'::text NOT NULL, payment_date date DEFAULT CURRENT_DATE NOT NULL, account_id uuid, reference text, transaction_id uuid, notes text, created_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.profiles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, tenant_id uuid, email text NOT NULL, full_name text, phone text, avatar_url text, is_active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, notification_preferences jsonb DEFAULT '{}'::jsonb NOT NULL, security_preferences jsonb DEFAULT '{}'::jsonb NOT NULL, PRIMARY KEY (id), UNIQUE (user_id));
CREATE TABLE public.sale_items (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, sale_id uuid NOT NULL, inventory_item_id uuid, production_record_id uuid, description text, salt_type text, quality_grade text, quantity numeric DEFAULT 0 NOT NULL, unit_price numeric DEFAULT 0 NOT NULL, total_price numeric DEFAULT 0 NOT NULL, unit_of_measure text DEFAULT 'Tonnes'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, warehouse_id uuid, warehouse_name text, amount_ht numeric GENERATED ALWAYS AS ((quantity * unit_price)) STORED, deleted_at timestamp with time zone, PRIMARY KEY (id));
CREATE TABLE public.sales (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, sale_number text NOT NULL, client_id uuid, campagne_id uuid, sale_date date DEFAULT CURRENT_DATE NOT NULL, delivery_date date, status sale_status DEFAULT 'draft'::sale_status NOT NULL, payment_status payment_status DEFAULT 'pending'::payment_status NOT NULL, is_export boolean DEFAULT false NOT NULL, can_be_delivered boolean DEFAULT false NOT NULL, subtotal numeric DEFAULT 0 NOT NULL, tax_amount numeric DEFAULT 0 NOT NULL, total_amount numeric DEFAULT 0 NOT NULL, total_paid numeric DEFAULT 0 NOT NULL, invoice_number text, notes text, created_by uuid, delivered_at timestamp with time zone, delivered_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, amount_paid numeric GENERATED ALWAYS AS (total_paid) STORED, salt_type text, quantity numeric, unit_price numeric, batch_number text, traceability_code text, sale_status sale_status DEFAULT 'draft'::sale_status NOT NULL, stock_updated boolean DEFAULT false NOT NULL, delivered boolean DEFAULT false NOT NULL, customer_name text, order_number text, warehouse_id uuid, tva_rate numeric DEFAULT 0 NOT NULL, tva_amount numeric DEFAULT 0 NOT NULL, amount_ht numeric DEFAULT 0 NOT NULL, discount numeric DEFAULT 0 NOT NULL, deleted_at timestamp with time zone, PRIMARY KEY (id));
CREATE TABLE public.stock_movements (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, inventory_item_id uuid, item_name text NOT NULL, movement_type stock_movement_type NOT NULL, quantity numeric DEFAULT 0 NOT NULL, previous_quantity numeric DEFAULT 0 NOT NULL, new_quantity numeric DEFAULT 0 NOT NULL, unit_cost numeric DEFAULT 0 NOT NULL, unit_of_measure text DEFAULT 'unité'::text NOT NULL, warehouse text, warehouse_from uuid, warehouse_to uuid, reference_type text, reference_id uuid, notes text, created_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.tenants (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, slug text, is_active boolean DEFAULT true NOT NULL, email text, phone text, address text, city text, country text DEFAULT 'Sénégal'::text, logo_url text, settings jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, subdomain text, contact_email text, contact_phone text, onboarding_completed boolean DEFAULT false NOT NULL, manager_name text, ninea text, rccm text, onboarding_step text, PRIMARY KEY (id), UNIQUE (slug));
CREATE TABLE public.transaction_lines (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, transaction_id uuid NOT NULL, account_id uuid NOT NULL, debit numeric(15,2) DEFAULT 0 NOT NULL, credit numeric(15,2) DEFAULT 0 NOT NULL, description text, line_order integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, CHECK (((debit >= (0)::numeric) AND (credit >= (0)::numeric))), CHECK ((NOT ((debit > (0)::numeric) AND (credit > (0)::numeric)))), PRIMARY KEY (id));
CREATE TABLE public.transactions (id uuid DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid DEFAULT get_user_tenant_id(auth.uid()) NOT NULL, reference text, journal_code text, transaction_date date DEFAULT CURRENT_DATE NOT NULL, transaction_type transaction_type DEFAULT 'od'::transaction_type NOT NULL, description text, amount numeric(15,2) DEFAULT 0 NOT NULL, status transaction_status DEFAULT 'draft'::transaction_status NOT NULL, account_id uuid, source_table text, source_id uuid, fiscal_period_id uuid, created_by uuid, validated_by uuid, validated_at timestamp with time zone, notes text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, is_validated boolean DEFAULT false NOT NULL, campagne_phase text, campagne_id uuid, PRIMARY KEY (id));
CREATE TABLE public.user_roles (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, role app_role NOT NULL, tenant_id uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, role, tenant_id));
CREATE TABLE public.quality_tests (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, production_record_id uuid, status text, deleted_at timestamptz);
